// 3-Way Reconciliation Comparison: Sheet vs Data Table vs Drive
// Strict Phase 1 Rule: DETECT + LOG + ALERT only. Never auto-repair.
const sheetRows = $('Read Marketing Queue Sheet').all().map(i => i.json);
const dtJobs = $('Read All Data Table Jobs').all().map(i => i.json).filter(j => j && j.internal_job_id);

const dtMap = {};
for (const j of dtJobs) {
  if (j.marketing_job) {
    dtMap[String(j.marketing_job).trim().toLowerCase()] = j;
  }
}

const discrepancies = [];

for (const sRow of sheetRows) {
  const mJobName = String(sRow['Marketing Job'] || '').trim();
  if (!mJobName) continue;

  const prodStatus = String(sRow['Production Status'] || '').trim();
  const schedStatus = String(sRow['Scheduling Status'] || '').trim();

  const dtJob = dtMap[mJobName.toLowerCase()];

  // If sheet is in an active post-intake lifecycle, it must exist in Data Table
  if (['Generating', 'Ready for Review', 'Approved', 'Ready to Schedule'].includes(prodStatus) ||
      ['Schedule Requested', 'Scheduled', 'Publish Confirmed', 'Published'].includes(schedStatus)) {

    if (!dtJob) {
      discrepancies.push({
        type: 'ORPHAN_SHEET_ROW',
        job_name: mJobName,
        business: sRow.Business,
        sheet_prod: prodStatus,
        sheet_sched: schedStatus,
        datatable_state: 'MISSING',
        drive_location: 'UNKNOWN',
        expected_drive: 'Expected internal job record in Data Table',
        severity: 'HIGH'
      });
      continue;
    }

    const dtProd = dtJob.production_status || '';
    const dtSched = dtJob.scheduling_status || '';
    const dtDriveLoc = dtJob.current_drive_location || '';

    // Check Lifecycle State Matrix Mismatches:
    // Case 1: Ready to Schedule / Not Scheduled
    if (prodStatus === 'Ready to Schedule' && schedStatus === 'Not Scheduled') {
      if (dtDriveLoc !== '01 Ready to Schedule') {
        discrepancies.push({
          type: 'DRIVE_LOCATION_MISMATCH',
          job_id: dtJob.internal_job_id,
          job_name: mJobName,
          business: sRow.Business,
          sheet_state: `${prodStatus} / ${schedStatus}`,
          datatable_state: `${dtProd} / ${dtSched}`,
          actual_drive_loc: dtDriveLoc,
          expected_drive: '01 Ready to Schedule',
          severity: 'HIGH'
        });
      }
    }

    // Case 2: Schedule Requested
    if (schedStatus === 'Schedule Requested') {
      if (dtDriveLoc !== '01 Ready to Schedule') {
        discrepancies.push({
          type: 'DRIVE_LOCATION_MISMATCH',
          job_id: dtJob.internal_job_id,
          job_name: mJobName,
          business: sRow.Business,
          sheet_state: `${prodStatus} / ${schedStatus}`,
          datatable_state: `${dtProd} / ${dtSched}`,
          actual_drive_loc: dtDriveLoc,
          expected_drive: '01 Ready to Schedule',
          severity: 'HIGH'
        });
      }
    }

    // Case 3: Scheduled
    if (schedStatus === 'Scheduled') {
      if (dtDriveLoc !== '02 Scheduled') {
        discrepancies.push({
          type: 'DRIVE_LOCATION_MISMATCH',
          job_id: dtJob.internal_job_id,
          job_name: mJobName,
          business: sRow.Business,
          sheet_state: `${prodStatus} / ${schedStatus}`,
          datatable_state: `${dtProd} / ${dtSched}`,
          actual_drive_loc: dtDriveLoc,
          expected_drive: '02 Scheduled',
          severity: 'HIGH'
        });
      }
    }

    // Case 4: Publish Confirmed
    if (schedStatus === 'Publish Confirmed') {
      if (dtDriveLoc !== '02 Scheduled') {
        discrepancies.push({
          type: 'DRIVE_LOCATION_MISMATCH',
          job_id: dtJob.internal_job_id,
          job_name: mJobName,
          business: sRow.Business,
          sheet_state: `${prodStatus} / ${schedStatus}`,
          datatable_state: `${dtProd} / ${dtSched}`,
          actual_drive_loc: dtDriveLoc,
          expected_drive: '02 Scheduled',
          severity: 'HIGH'
        });
      }
    }

    // Case 5: Published
    if (schedStatus === 'Published') {
      if (dtDriveLoc !== '06 Published Content') {
        discrepancies.push({
          type: 'DRIVE_LOCATION_MISMATCH',
          job_id: dtJob.internal_job_id,
          job_name: mJobName,
          business: sRow.Business,
          sheet_state: `${prodStatus} / ${schedStatus}`,
          datatable_state: `${dtProd} / ${dtSched}`,
          actual_drive_loc: dtDriveLoc,
          expected_drive: '06 Published Content',
          severity: 'HIGH'
        });
      }
    }
  }
}

return [{
  json: {
    reconciliation_timestamp: new Date().toISOString(),
    total_checked: sheetRows.length,
    mismatch_count: discrepancies.length,
    has_discrepancies: discrepancies.length > 0,
    discrepancies: discrepancies
  }
}];

// Prepare individual log rows and alert email content
const recon = $json;
const list = recon.discrepancies || [];

const logRows = list.map(d => ({
  error_id: `ERR_RECON_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`,
  timestamp: recon.reconciliation_timestamp,
  workflow: 'WF-98',
  internal_job_id: d.job_id || 'N/A',
  business: d.business || 'N/A',
  node: '3-Way Reconciliation Matrix',
  error_type: 'BUSINESS_RULE',
  error_message: `[${d.type}] Sheet: '${d.sheet_state || d.sheet_prod}' | Data Table: '${d.datatable_state}' | Actual Drive: '${d.actual_drive_loc || d.drive_location}' | Expected: '${d.expected_drive}'`,
  retry_count: 0,
  resolved: false,
  resolution: 'DETECTED_AWAITING_HUMAN_REVIEW'
}));

return logRows.map(r => ({ json: r }));

// Reconciliation 100% clean. All states aligned.
return [{
  json: {
    status: 'ALL_SYNCED',
    timestamp: new Date().toISOString(),
    message: '3-way reconciliation check passed: Google Sheets, Data Table, and Google Drive are fully consistent.'
  }
}];
